// In-memory module registry (simulates file system)
const MODULE_REGISTRY = {
  'entry.js': {
    code: "const { greet } = require('./utils');\nconsole.log(greet('World'));",
    deps: ['./utils']
  },
  './utils': {
    code: "function greet(name) { return 'Hello, ' + name + '!'; }\nmodule.exports = { greet };",
    deps: []
  }
};

function buildGraph(entryId) {
  const modules = [];
  const visited = new Set();

  function traverse(moduleId) {
    if (visited.has(moduleId)) return;
    visited.add(moduleId);
    const mod = MODULE_REGISTRY[moduleId];
    if (!mod) return;
    modules.push({ id: moduleId, code: mod.code, deps: mod.deps });
    for (const dep of mod.deps) {
      traverse(dep);
    }
  }

  traverse(entryId);
  return modules;
}

const graph = buildGraph('entry.js');
console.log(JSON.stringify(graph, null, 2));

