function minify(code) {
  let min = code
    .replace(/\/\/.*$/gm, '')
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/\n\s+/g, '\n')
    .replace(/\s+\n/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/;\s*}/g, '}')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  return min;
}

