import re

class TransformPipeline:
    def __init__(self, plugins):
        self.plugins = plugins

    def process(self, code):
        result = code
        for plugin in self.plugins:
            result = plugin(result)
            print('After plugin:', result[:60] + '...')
        return result


def strip_logs(code):
    return re.sub(r'print\([^)]*\);?', '# log removed', code)

def add_strict(code):
    return '"use strict";\n' + code

def remove_comments(code):
    return re.sub(r'#.*$', '', code, flags=re.MULTILINE)


pipeline = TransformPipeline([add_strict, strip_logs, remove_comments])

input_code = '''
def hello():
    # Print greeting
    print("Hello, world!")
    return 42
'''

print('--- Input ---')
print(input_code)
print('--- Final Output ---')
print(pipeline.process(input_code))
